Translate("frFR", "mulgore", {
	title = "Mulgore",
	aliases = { "les plaines de Mulgore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mulgore est la patrie des {link:tauren}taurens{/link}, un vaste pays d'herbe dorée et de douces collines, ceint de montagnes de tous côtés. Des troupeaux de kodos paissent dans ses plaines, et des puits et des lacs limpides abreuvent la terre. Au-dessus de tout cela se dressent les grandes mesas de {link:thunder-bluff}Thunder Bluff{/link}, la capitale des taurens, où le grand chef {link:cairne-bloodhoof}Cairne Bloodhoof{/link} tient sa hutte. Pour les taurens, c'est le don de la {red:earth-mother}Terre-mère{/red}, une terre paisible après des siècles d'errance. Pourtant, hurans, gnolls, harpies et gobelins pressent sur chacune de ses lisières, et les jeunes des tribus doivent faire leurs preuves contre eux.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant d'innombrables générations, les taurens furent des nomades qui suivaient les troupeaux à travers les plaines de {link:kalimdor}Kalimdor{/link}. Les {link:centaurs}centaures{/link} les traquèrent sans pitié, les chassèrent de leurs anciennes terres et dispersèrent leurs tribus. {link:cairne-bloodhoof}Cairne{/link}, des Bloodhoof, entreprit de rassembler son peuple et de le mener vers une terre où il pourrait vivre en sécurité.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les centaures furent repoussés, mais Mulgore n'est pas en paix. Les {link:bristleback-quilboar}hurans Dos-hirsute{/link} font la guerre aux jeunes taurens de la {link:red-cloud-mesa}Mesa de Nuage rouge{/link} et profanent le cimetière des {link:red-rocks}Rochers rouges{/link}. Les {link:palemane-gnolls}gnolls Crins-pâles{/link} chassent la faune jusqu'à la ruine et répondent à chaque parole de paix par des lames. Les {link:windfury-harpies}harpies Furies-des-vents{/link} nichent sur les crêtes. Les gobelins de la {link:venture-company}KapitalRisk{/link} ont empoisonné les puits sacrés et creusé une mine dans les falaises de l'est, et des nains fouillent le sol à l'ouest en quête de vieux secrets. En ces jours, une bande de centaures Galak a de nouveau été vue à l'intérieur des frontières, et un {link:longwalkers}Longwalker{/link} envoyé surveiller l'est n'est pas rentré. Au nord-ouest, les chamans du {link:earthen-ring}Cercle terrestre{/link} ont dressé un camp où arrive un peuple étrange venu du ciel : des elfes {link:skyborne}Skyborne{/link} des {link:windshapers}Windshapers{/link}, descendus de {link:skywall}Skywall{/link} pour chercher de nouveaux alliés.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les taurens.{/b} Chasseurs, chamans, druides et braves vivent au {link:camp-narache}Camp Narache{/link}, au {link:bloodhoof-village}Village Bloodhoof{/link} et dans la cité d'en haut. Le chef {link:baine-bloodhoof}Baine Bloodhoof{/link}, fils de {link:cairne-bloodhoof}Cairne{/link}, dirige le village.
• {b}Le {link:earthen-ring}Cercle terrestre{/link}.{/b} Des chamans de plusieurs peuples se rassemblent au {link:camp-gev-rek}Camp Gev'rek{/link} sous l'autorité de {link:muln-earthfury}Muln Earthfury{/link}.
• {b}Les {link:bristleback-quilboar}hurans Dos-hirsute{/link}.{/b} Ils tiennent le {link:brambleblade-ravine}Ravin de Roncelame{/link} et attaquent la mesa et les plaines.
• {b}Les {link:palemane-gnolls}gnolls Crins-pâles{/link}.{/b} Ils ont leur repaire au {link:palemane-rock}Rocher des crins-pâles{/link} et dans des camps le long des collines du sud.
• {b}Les {link:windfury-harpies}harpies Furies-des-vents{/link}.{/b} Elles nichent sur les bords des montagnes du sud-est et sur la {link:windfury-ridge}Crête des Furies-des-vents{/link}.
• {b}{link:venture-company}La KapitalRisk{/link}.{/b} Des mineurs, des bûcherons et des contremaîtres gobelins qui veulent vider la terre de son peuple.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La longue marche.{/b} Près des rivages de la Grande mer, le jeune chef de guerre {link:thrall}Thrall{/link} trouva le peuple de {link:cairne-bloodhoof}Cairne{/link} attaqué par les centaures. Les orcs escortèrent les caravanes taurens à travers les {link:the-barrens}Tarides{/link} jusqu'à Mulgore, et en retour Cairne montra à Thrall le chemin de l'Oracle des {link:stonetalon-mountains}Serres-Rocheuses{/link}.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Cairne engagea son peuple aux côtés de la {link:horde}Horde{/link}, et des guerriers taurens combattirent aux côtés des orcs lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.
• {b}La conquête de Mulgore.{/b} Avec l'aide de la Horde, les taurens brisèrent l'emprise des centaures sur les plaines et firent de Mulgore une patrie permanente pour toutes leurs tribus. Sur les mesas, ils élevèrent {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
		{
			title = "Légendes des plaines",
			text = [=[• Un jeune {link:tauren}tauren{/link} gagne sa place à {link:thunder-bluff}Thunder Bluff{/link} par les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, qui mènent du {link:camp-narache}Camp Narache{/link} jusqu'à la hutte du grand chef.
• Dans les collines du sud-est, au-dessus de la mesa, se dresse un sanctuaire dédié à An'she et Mu'sha, le soleil et la lune. Les taurens honorent les jumeaux parce que leur lumière donne la vie et guide, bien qu'ils ne soient pas de ce monde comme le sont les éléments.
• À l'ouest du Lac Taureau-de-pierre, un loup des prairies que les chasseurs appellent Chakuyak rôde d'un bosquet à l'autre.]=],
		},
	},
})

Translate("frFR", "red-cloud-mesa", {
	title = "Mesa de Nuage rouge",
	sections = {
		{
			title = "Résumé",
			text = [=[La Mesa de Nuage rouge est le haut plateau du sud de {link:mulgore}Mulgore{/link}, où les jeunes taurens font leurs premiers pas de chasseurs. Des trotteurs des plaines et des couguars des montagnes parcourent son herbe, et les anciens disent que ses habitants s'enorgueillissent avant tout de leur habileté à la chasse. Un puits se trouve au sud-est du camp, où la Grand-mère des {link:chief-hawkwind}Hawkwind{/link} puise l'eau. Dans les collines au sud, le voyant {link:seer-graytongue}Graytongue{/link} a sa demeure, et au-dessus des lointaines pentes du sud-est se dresse un sanctuaire dédié à An'she et Mu'sha. À l'est de la mesa s'ouvre le {link:brambleblade-ravine}Ravin de Roncelame{/link}, d'où les {link:bristleback-quilboar}hurans Dos-hirsute{/link} viennent la nuit tendre des embuscades aux chasseurs et voler au camp.]=],
		},
	},
})

Translate("frFR", "camp-narache", {
	title = "Camp Narache",
	aliases = { "Narache" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp Narache est le camp du chef {link:chief-hawkwind}Hawkwind{/link} sur la {link:red-cloud-mesa}Mesa de Nuage rouge{/link}. C'est un lieu de tentes, de totems et de feux de cuisine, et c'est là que les jeunes de la tribu commencent les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}. Le chef enseigne que chaque membre de la tribu a sa place dans l'équilibre des êtres vivants, et que les anciens remarquent même les humbles travaux. Son fils {link:grull-hawkwind}Grull{/link} met à l'épreuve les jeunes chasseurs. Le camp vit sous la menace, car le chef de guerre des {link:bristleback-quilboar}Dos-hirsute{/link} a dressé des plans pour l'assiéger. Ceux qui font leurs preuves ici suivent la route vers le nord jusqu'au {link:bloodhoof-village}Village Bloodhoof{/link}.]=],
		},
	},
})

Translate("frFR", "brambleblade-ravine", {
	title = "Ravin de Roncelame",
	aliases = { "Roncelame" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Ravin de Roncelame entaille les collines à l'est de la {link:red-cloud-mesa}Mesa de Nuage rouge{/link}. Il est envahi d'épines, et les {link:bristleback-quilboar}hurans Dos-hirsute{/link} y ont bâti un village grossier. De là, leurs pillards se glissent sur la mesa pour tendre des embuscades aux groupes de chasse du {link:camp-narache}Camp Narache{/link}. Les hurans dressent des sangliers de guerre dans le ravin et leur apprennent la férocité. Leur chef, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, a sa hutte au cœur du ravin, et les taurens de Narache disent que sa guerre contre eux a coûté bien des vies depuis leur arrivée sur cette terre.]=],
		},
	},
})

Translate("frFR", "bloodhoof-village", {
	title = "Village Bloodhoof",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Village Bloodhoof se trouve au cœur de {link:mulgore}Mulgore{/link}, sur la route entre la {link:red-cloud-mesa}Mesa de Nuage rouge{/link} et {link:thunder-bluff}Thunder Bluff{/link}. C'est le village de la tribu même de {link:cairne-bloodhoof}Cairne{/link}, et son fils {link:baine-bloodhoof}Baine{/link} le dirige en tant que chef. Autour de son grand feu se rassemblent les maîtres de la tribu : le chaman {link:mull-thunderhorn}Mull Thunderhorn{/link}, qui purifie les puits empoisonnés, le guide spirituel {link:zarlman-two-moons}Zarlman Two-Moons{/link}, le guerrier {link:ruul-eagletalon}Ruul Eagletalon{/link} et les chasseurs {link:harken-windtotem}Harken Windtotem{/link} et {link:skorn-whitecloud}Skorn Whitecloud{/link}. Son auberge accueille les voyageurs. Du Village Bloodhoof, les jeunes taurens partent vers les puits, la mine et les camps de gnolls, et ceux qui réussissent le Rite de vision partent d'ici vers la cité.]=],
		},
	},
})

Translate("frFR", "water-wells-of-mulgore", {
	title = "Puits de Mulgore",
	aliases = { "Puits Winterhoof", "Puits Thunderhorn", "Puits Wildmane", "puits de Mulgore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Trois puits sacrés abreuvent {link:mulgore}les plaines de Mulgore{/link}, chacun portant le nom d'un clan {link:tauren}tauren{/link}. Le Puits Winterhoof se trouve au sud-est du {link:bloodhoof-village}Village Bloodhoof{/link}, le Puits Thunderhorn au nord de celui-ci, et le Puits Wildmane au nord de {link:thunder-bluff}Thunder Bluff{/link}. Les puits donnent la vie aux taurens et aux bêtes dont ils dépendent. Les gobelins de la {link:venture-company}KapitalRisk{/link} et leurs serviteurs les ont souillés tous les trois. Pour les purifier, le chaman {link:mull-thunderhorn}Mull Thunderhorn{/link} fabrique pour chacun un totem avec ce que la terre elle-même offre, et un rituel doit ensuite être accompli au puits, souvent sous les yeux des gardes gobelins.]=],
		},
	},
})

Translate("frFR", "the-venture-co-mine", {
	title = "Mine de la KapitalRisk",
	aliases = { "Mine de la KapitalRisk" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Mine de la KapitalRisk est creusée dans les falaises de l'est de {link:mulgore}Mulgore{/link}, au nord-est du Lac Taureau-de-pierre. Les gobelins de la {link:venture-company}KapitalRisk{/link} y extraient du minerai et des minéraux de la terre des taurens, sans permission. Leur superviseur, {link:supervisor-fizsprocket}Fizsprocket{/link}, gardait des plans pour chasser entièrement les taurens de Mulgore, afin que la compagnie puisse piller les plaines à sa guise. Ses notes parlent aussi de déchiqueteurs, de grandes machines qui peuvent abattre une forêt en quelques jours, et des projets de la compagnie de s'étendre plus loin à travers le pays.]=],
		},
	},
})

Translate("frFR", "ravaged-caravan", {
	title = "Caravane dévastée",
	sections = {
		{
			title = "Résumé",
			text = [=[La Caravane dévastée se trouve sur la rive nord du Lac Taureau-de-pierre. C'était un convoi de la {link:venture-company}KapitalRisk{/link} voyageant sous escorte, et les taurens, qui avaient perdu deux des leurs face aux gobelins dans un combat précédent, tombèrent sur lui et l'incendièrent. Ils laissèrent derrière eux les caisses de provisions, pensant que le feu les avait gâtées. Il n'en était rien. Les caisses contenaient du minerai pris à {link:mulgore}Mulgore{/link} et une liasse de papiers qui révélait l'ampleur de l'exploitation minière de la compagnie sur les terres des taurens.]=],
		},
	},
})

Translate("frFR", "palemane-rock", {
	title = "Rocher des crins-pâles",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rocher des crins-pâles est une grotte dans les collines de l'ouest de {link:mulgore}Mulgore{/link}, le repaire des {link:palemane-gnolls}gnolls Crins-pâles{/link}. De là, les gnolls partent braconner les troupeaux, dépecer leurs proies et tanner les peaux, prenant bien plus que la terre ne peut donner. Les taurens tentèrent de leur parler et furent reçus avec mépris. En ces jours, le grand chef envoya un {link:longwalkers}Longwalker{/link}, {link:perith-stormhoof}Perith Stormhoof{/link}, tenter une fois encore. Les gnolls répondirent par la violence, et Perith fut retenu dans le rocher, craignant de devenir leur festin.]=],
		},
	},
})

Translate("frFR", "bael-dun-digsite", {
	title = "Site de fouilles de Bael'Dun",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Site de fouilles de Bael'Dun se trouve à l'ouest de {link:mulgore}Mulgore{/link}, au nord-ouest du {link:bloodhoof-village}Village Bloodhoof{/link}. Des {link:dwarves}nains{/link} y ont dressé un camp et creusent la terre, avec des fouilleurs pour briser le sol et des estimateurs pour juger ce qu'ils trouvent. Ils croient que des secrets sont enfouis en Mulgore. Le chef {link:baine-bloodhoof}Baine Bloodhoof{/link} n'en doute pas. Il tient seulement qu'éventrer et souiller la terre n'est pas la bonne façon d'apprendre ses secrets, et il a demandé que les outils de fouille des nains soient pris et brisés.]=],
		},
	},
})

Translate("frFR", "red-rocks", {
	title = "Rochers rouges",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Rochers rouges sont le cimetière sacré des taurens, au nord-est de {link:mulgore}Mulgore{/link}, au-delà de {link:thunder-bluff}Thunder Bluff{/link}. Seuls les plus vaillants y reposent : les guerriers qui aidèrent à fonder et à défendre la cité, et ceux qui donnèrent leur vie pour leurs tribus et leurs chefs. Des esprits ancestraux demeurent parmi les pierres, et c'est ici que les jeunes taurens qui ont bu l'Eau des voyants viennent recevoir la bénédiction de leurs aïeux. Le vieux gardien du savoir {link:lorekeeper-raintotem}Raintotem{/link} veille sur les tombes. Des pillards {link:bristleback-quilboar}Dos-hirsute{/link} sont venus récemment sur la terre sacrée pour la ravager.]=],
		},
	},
})

Translate("frFR", "windfury-ridge", {
	title = "Crête des Furies-des-vents",
	sections = {
		{
			title = "Résumé",
			text = [=[La Crête des Furies-des-vents est la haute bordure nord de {link:mulgore}Mulgore{/link}, où les plaines montent vers les montagnes. C'est la place forte des {link:windfury-harpies}harpies Furies-des-vents{/link}. Leurs matriarches et leurs ensorceleuses se perchent parmi les rochers escarpés, et leurs sorcières invoquent le vent. Les taurens comptent les harpies parmi les ennemis naturels de Mulgore, et pourtant ils prisent les plumes azur et bronze des volées du nord pour les coiffes que l'on porte devant le grand chef. On dit que la {link:harpies}harpie{/link} Sœur Hatelash mène les volées du nord-ouest.]=],
		},
	},
})

Translate("frFR", "the-golden-plains", {
	title = "Les plaines dorées",
	aliases = { "plaines dorées" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les plaines dorées s'étendent à l'est de {link:thunder-bluff}Thunder Bluff{/link}, une mer de hautes herbes entre la cité et les falaises de l'est. Des couguars des plaines y chassent, et l'on dit que le vieux trotteur {link:mazzranache}Mazzranache{/link} parcourt la même contrée. De temps à autre, un grand loup blanc nommé {link:ghost-howl}Ghost Howl{/link} traverse ces plaines, la peau encore couturée de cicatrices d'un combat contre des démons. Les gobelins de la {link:venture-company}KapitalRisk{/link} tracent leurs routes à travers l'herbe entre leur mine et les puits. En ces jours, l'un de leurs déchiqueteurs a été vu dans les plaines, une machine que les taurens ne toléreront pas d'abattre un seul arbre de {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("frFR", "camp-gev-rek", {
	title = "Camp Gev'rek",
	aliases = { "Skywatcher Plateau" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Camp Gev'rek se dresse sur le Skywatcher Plateau, au nord-ouest de {link:mulgore}Mulgore{/link}. C'est un rassemblement du {link:earthen-ring}Cercle terrestre{/link} : des chamans taurens, un troll, et même l'un des Totem sinistre, menés par {link:muln-earthfury}Muln Earthfury{/link} et l'ancienne clairvoyante Nuara Tremorhoof. C'est ici que les navires fendeurs de ciel des {link:windshapers}Windshapers{/link} descendent de {link:zephras-isle}Zephras Isle{/link}, apportant des elfes {link:skyborne}Skyborne{/link} dans un monde qu'ils n'ont jamais vu. {link:alaana-stormwalker}Alaana Stormwalker{/link} accueille chaque nouvel arrivant. À côté du camp, un marchand gobelin, une prêtresse d'An'she et des dresseurs de galestriders skyborne ont installé leurs étals.]=],
		},
	},
})

Translate("frFR", "chief-hawkwind", {
	title = "Chef Hawkwind",
	subtitle = "Chef du Camp Narache",
	found = "Le Camp Narache, sur la Mesa de Nuage rouge",
	hint = "Parlez au chef qui veille sur les jeunes du Camp Narache.",
	allegiance = "Taurens · Camp Narache",
	aliases = { "Hawkwind" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le chef Hawkwind dirige le {link:camp-narache}Camp Narache{/link}, où les jeunes taurens de {link:mulgore}Mulgore{/link} commencent leur vie de chasseurs et de guerriers. Il enseigne que la tribu vit et travaille ensemble, et que chacun de ses membres porte une part de ses fardeaux. Il place devant les jeunes le premier des {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, et il envoie ceux qui réussissent auprès de {link:baine-bloodhoof}Baine Bloodhoof{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Pour beaucoup de taurens, la parole de Hawkwind est le premier jugement de leur valeur. Il croit que l'humble service est le commencement de la grandeur.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes aider sa mère au puits.
• Il fixe le Rite de force, et envoie les jeunes auprès du voyant {link:seer-graytongue}Graytongue{/link}.
• Il apprend les plans des {link:bristleback-quilboar}Dos-hirsute{/link} pour assiéger son camp.
• Il sculpte un totem que {link:baine-bloodhoof}Baine{/link} reconnaît comme son œuvre.]=],
		},
	},
	mentions = {
		{ text = "Une humble tâche" },
		{
			text = [=[Les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}]=],
		},
		{ text = "Le Rite de force" },
		{
			text = [=[Les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, envoyé au {link:bloodhoof-village}Village Bloodhoof{/link}]=],
		},
		{ text = "L'attaque du {link:camp-narache}Camp Narache{/link}" },
		{ text = "L'aventurière" },
	},
	bonds = {
		{ id = "greatmother-hawkwind", name = "Grand-mère Hawkwind", note = "sa mère" },
		{ id = "grull-hawkwind", name = "Grull Hawkwind", note = "son fils" },
		{ id = "seer-graytongue", name = "Voyant Graytongue", note = "met les jeunes à l'épreuve sur sa parole" },
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "reçoit ceux qui réussissent" },
	},
})

Translate("frFR", "grull-hawkwind", {
	title = "Grull Hawkwind",
	subtitle = "Chasseur de la Mesa de Nuage rouge",
	found = "Le Camp Narache, sur la Mesa de Nuage rouge",
	hint = [=[Trouvez le fils du chef, qui met à l'épreuve les jeunes chasseurs de Narache.]=],
	allegiance = "Taurens · Camp Narache",
	aliases = { "Grull" },
	sections = {
		{
			title = "Résumé",
			text = [=[Grull Hawkwind est le fils du chef {link:chief-hawkwind}Hawkwind{/link} et un chasseur de la {link:red-cloud-mesa}Mesa de Nuage rouge{/link}. Il met à l'épreuve les jeunes qui arrivent au {link:camp-narache}Camp Narache{/link} avant qu'ils ne se présentent devant son père. Il enseigne que les taurens chassent par nécessité autant que par sport, et qu'une bête est prise pour nourrir et vêtir la tribu, jamais comme un simple trophée.]=],
		},
		{
			title = "Importance",
			text = [=[Grull donne aux jeunes leur première chasse, et avec elle la première leçon de la vie {link:tauren}tauren{/link} : ne prendre à la terre que ce dont la tribu a besoin.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes chasser les trotteurs des plaines pour leur viande et leurs plumes.
• Il demande des peaux de couguar des montagnes pour vêtir les enfants et réparer les tentes.
• Il envoie des chasseurs contre les sangliers de guerre du {link:brambleblade-ravine}Ravin de Roncelame{/link}.]=],
		},
	},
	mentions = {
		{ text = "La chasse commence" },
		{ text = "La chasse continue" },
		{ text = "Les sangliers de guerre" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "son père" },
	},
})

Translate("frFR", "greatmother-hawkwind", {
	title = "Grand-mère Hawkwind",
	subtitle = "Doyenne des Hawkwind",
	found = "Le puits au sud-est du Camp Narache",
	hint = [=[Cherchez la vieille femme qui puise l'eau au puits au sud-est de Narache.]=],
	allegiance = "Taurens · Camp Narache",
	sections = {
		{
			title = "Résumé",
			text = [=[La Grand-mère Hawkwind est la mère du chef {link:chief-hawkwind}Hawkwind{/link}. Chaque matin, elle marche jusqu'au puits au sud-est du {link:camp-narache}Camp Narache{/link} pour chercher de l'eau pour la tribu. Un matin, elle fut absente si longtemps que son fils commença à s'inquiéter. Ses jambes ont perdu la force qu'elles avaient autrefois, mais elle ne renoncera pas à ses devoirs. Elle met simplement un peu plus de temps qu'avant.]=],
		},
		{
			title = "Importance",
			text = [=[La Grand-mère enseigne aux jeunes une leçon chère à son fils : la plus petite tâche, bien faite, gagne le respect des anciens.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche l'eau pour le {link:camp-narache}Camp Narache{/link}.
• Elle donne aux jeunes une cruche à porter à son fils.]=],
		},
	},
	mentions = {
		{ text = "Une humble tâche" },
		{ text = "Une humble tâche, la cruche d'eau" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "son fils" },
	},
})

Translate("frFR", "seer-graytongue", {
	title = "Voyant Graytongue",
	subtitle = "Voyant de la Mesa de Nuage rouge",
	found = "Sa demeure dans les collines au sud du Camp Narache",
	hint = [=[Cherchez le voyant dont la demeure est nichée dans les collines au sud de Narache.]=],
	allegiance = "Taurens · Camp Narache",
	aliases = { "Graytongue" },
	sections = {
