			title = "Résumé",
			text = [=[Le voyant Graytongue vit seul dans les collines au sud du {link:camp-narache}Camp Narache{/link}. C'est à lui qu'on envoie les jeunes pour commencer le Rite de force, le premier des {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}. Il garde aussi vivante une vieille vénération : l'honneur rendu à An'she et Mu'sha, le soleil et la lune, dont la lumière donne aux taurens la vie, la direction et l'espoir.]=],
		},
		{
			title = "Importance",
			text = [=[Graytongue se tient au seuil des rites. Il envoie les jeunes contre les {link:bristleback-quilboar}Dos-hirsute{/link}, qui menacent la tribu depuis l'est.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fixe le Rite de force : tuer des pillards {link:bristleback-quilboar}Dos-hirsute{/link} et rapporter leurs ceintures.
• Il envoie de l'encens fumant au sanctuaire du soleil et de la lune, dans les collines du sud-est.]=],
		},
	},
	mentions = {
		{
			text = [=[Les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}]=],
		},
		{ text = "Le Rite de force" },
		{ text = "La grâce d'An'she et Mu'sha" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "lui envoie les jeunes" },
	},
})

Translate("frFR", "baine-bloodhoof", {
	title = "Baine Bloodhoof",
	subtitle = "Chef du Village Bloodhoof",
	found = "Le centre du Village Bloodhoof",
	hint = [=[Cherchez le fils du grand chef, qui dirige le Village Bloodhoof.]=],
	allegiance = "Taurens · Tribu Bloodhoof · Horde",
	aliases = { "Baine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Baine Bloodhoof est le fils de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} et le chef du {link:bloodhoof-village}Village Bloodhoof{/link}. Il gouverne le cœur de {link:mulgore}Mulgore{/link} tandis que son père gouverne depuis {link:thunder-bluff}Thunder Bluff{/link}. Il est patient avec ceux qui veulent partager la terre, et sévère avec ceux qui s'y refusent. Il a vu bien des conflits qui blessent le monde, et il espère que les jeunes de sa tribu en verront moins.]=],
		},
		{
			title = "Importance",
			text = [=[Baine est la génération suivante des Bloodhoof. Les jeunes qui passent par son village apprennent de lui ce que signifie défendre la patrie des taurens.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il poursuit les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, et envoie les jeunes auprès du guide spirituel {link:zarlman-two-moons}Zarlman Two-Moons{/link} pour le Rite de vision.
• Il ordonna de repousser les {link:palemane-gnolls}gnolls Crins-pâles{/link} quand ils refusèrent toute tentative de paix.
• Il ordonna la destruction des outils des fouilleurs nains.
• Il fait parfois appel aux {link:longwalkers}Longwalkers{/link}, les éclaireurs de son père.
• Il mena en ces jours la défense contre un groupe de pillards Galak.]=],
		},
	},
	chapters = {
		{
			title = "Partager la terre",
			hint = "Apprenez le jugement du chef sur les gnolls de Mulgore.",
			text = [=[Les {link:palemane-gnolls}gnolls Crins-pâles{/link} vinrent en {link:mulgore}Mulgore{/link} et massacrèrent sa faune sans retenue. Les taurens tentèrent encore et encore de les atteindre par la parole. Baine conclut enfin que les mots n'étaient plus la réponse. Il voulait montrer aux jeunes combien même une petite menace peut devenir terrible si on la laisse sans frein.]=],
		},
		{
			title = "Notre ennemi ancestral",
			hint = "Occupez-vous des centaures qui ont pénétré en Mulgore.",
			text = [=[Quand le rapport de la {link:longwalkers}Longwalker{/link} Malah, tuée, lui parvint, Baine le lut en silence. Puis il déclara que les taurens ne céderaient pas un seul brin d'herbe aux centaures. Il envoya des guerriers frapper le camp Galak avant que ses cavaliers ne puissent atteindre son village, et demanda que la tête de leur chef soit rapportée en avertissement pour les autres.]=],
		},
		{
			title = "Le fils captif",
			hint = [=[Apprenez ce qu'il en fut des jours où Baine fut pris par les centaures.]=],
			text = [=[Dans les mois qui suivirent l'installation des taurens en {link:mulgore}Mulgore{/link}, des centaures s'emparèrent de Baine. Son père sombra dans un désespoir si profond qu'il ne voulut plus mener son peuple. Ce furent l'{link:orcs}orc{/link} {link:rexxar}Rexxar{/link} et le {link:tauren}tauren{/link} Bovan Windtotem qui trouvèrent Baine et le ramenèrent chez lui. Quand Baine envoie aujourd'hui les jeunes à son père, il parle avec fierté du jour où {link:cairne-bloodhoof}Cairne{/link} chevaucha avec {link:thrall}Thrall{/link} pour reprendre ces plaines.]=],
		},
	},
	mentions = {
		{
			text = [=[Les {link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, apportés par le chef {link:chief-hawkwind}Hawkwind{/link}]=],
		},
		{ text = "Le Rite de vision" },
		{ text = "Fouilles naines" },
		{ text = "Notre ennemi ancestral, le rapport qu'il reçut" },
		{ text = "Le grand chef" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "son père" },
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "lui envoie les jeunes" },
		{ id = "zarlman-two-moons", name = "Zarlman Two-Moons", note = "guide spirituel de son village" },
		{ id = "brave-wildrunner", name = "Brave Wildrunner", note = "un brave de son village" },
		{ id = "herak-the-pillager", name = "Herak le Pillard", note = "ennemi" },
	},
})

Translate("frFR", "harken-windtotem", {
	title = "Harken Windtotem",
	subtitle = "Chasseur de Bloodhoof",
	found = "Le Village Bloodhoof",
	hint = [=[Parlez au chasseur de Bloodhoof qui prise les pennes du plongeur.]=],
	allegiance = "Taurens · Village Bloodhoof",
	aliases = { "Harken" },
	sections = {
		{
			title = "Résumé",
			text = [=[Harken Windtotem est un chasseur du {link:bloodhoof-village}Village Bloodhoof{/link}. Il enseigne que le plongeur est un oiseau rusé, difficile à trouver et plus difficile encore à attraper. Pour lui, un chasseur qui rassemble ses pennes a fait preuve d'intelligence et de détermination, et a fait honneur à son clan. Les plongeurs volent partout en {link:mulgore}Mulgore{/link}, dit-il, mais seuls des yeux perçants les repèrent et seuls des sabots rapides les attrapent.]=],
		},
		{
			title = "Importance",
			text = [=[Harken garde la vieille croyance {link:tauren}tauren{/link} selon laquelle une chasse met à l'épreuve le caractère du chasseur, et pas seulement sa force.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes chasseurs à travers les plaines à la recherche du plongeur.
• Il tient une collection de pennes de plongeur pour une marque de la valeur du chasseur.]=],
		},
	},
	mentions = {
		{ text = "La chasse au plongeur" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "son chef" },
	},
})

Translate("frFR", "maur-raincaller", {
	title = "Maur Raincaller",
	subtitle = "Tauren de Bloodhoof",
	found = "Le Village Bloodhoof",
	hint = [=[Trouvez le tauren de Bloodhoof qui porte la morsure d'une vieille bête.]=],
	allegiance = "Taurens · Village Bloodhoof",
	aliases = { "Maur" },
	sections = {
		{
			title = "Résumé",
			text = [=[Maur Raincaller a grandi avec les récits de son grand-père sur {link:mazzranache}Mazzranache{/link}, un trotteur aux yeux rouges démoniaques, aux serres acérées et à la morsure venimeuse. Il n'y voyait que des histoires, jusqu'à ce qu'il rencontre lui-même la bête dans les plaines. Elle lui déchira à l'épaule une blessure qui ne guérit pas, et il a besoin de parties rares de loup, de couguar, de trotteur des plaines et de plongeur pour en extraire le poison.]=],
		},
		{
			title = "Importance",
			text = [=[La blessure de Maur prouve que les vieux récits de {link:mulgore}Mulgore{/link} ne sont pas toujours des récits. Son grand-père disait vrai : le trotteur était aussi terrible qu'il l'avait décrit. Le poison agit vite, et Maur prévient que le temps presse.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il survécut à la morsure de {link:mazzranache}Mazzranache{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:mazzranache}Mazzranache{/link}" },
	},
	bonds = {
		{ id = "mazzranache", name = "Mazzranache", note = "la bête qui l'a mordu" },
	},
})

