		},
		{ text = "Totem Wildmane" },
		{
			text = [=[Purification du {link:water-wells-of-mulgore}Puits Wildmane{/link}]=],
		},
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "a reçu son rapport" },
	},
})

