		},
	},
	mentions = {
		{ text = "Le Rite de vision" },
		{ text = "Le Rite de vision, les composants" },
		{ text = "Le Rite de vision, l'Eau des voyants" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "son chef" },
		{ id = "seer-wiserunner", name = "Voyant Wiserunner", note = "attend là où mène la vision" },
	},
})

