	sections = {
		{
			title = "Résumé",
			text = [=[Ruul Eagletalon se dit guerrier et maître. Il guette le moment où un jeune {link:tauren}tauren{/link} est prêt à aller plus loin que les plaines natales. Il tient qu'un tauren doit se préparer aux épreuves avant de s'aventurer bien loin de chez lui. Ceux qui veulent mettre leur force à l'épreuve, il les envoie contre les {link:windfury-harpies}harpies Furies-des-vents{/link}, qu'il compte parmi les ennemis naturels de {link:mulgore}Mulgore{/link}.]=],
