		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes contre les {link:windfury-harpies}harpies Furies-des-vents{/link} du sud-est.]=],
		},
	},
	mentions = {
		{
			text = [=[Les dangers des {link:windfury-harpies}Furies-des-vents{/link}]=],
		},
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "son chef" },
	},
})

