		{ id = "ghost-howl", name = "Ghost Howl", note = "le loup de ses récits" },
	},
})

Translate("frFR", "lorekeeper-raintotem", {
	title = "Gardien du savoir Raintotem",
	subtitle = "Gardien des Rochers rouges",
	found = "Les Rochers rouges",
	hint = "Cherchez le vieux gardien du savoir au cimetière sacré.",
	allegiance = "Taurens",
	aliases = { "Raintotem" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le gardien du savoir Raintotem veille sur les {link:red-rocks}Rochers rouges{/link}, le cimetière sacré des taurens. Il connaît les noms des vaillants qui y reposent, les fondateurs et les défenseurs de {link:thunder-bluff}Thunder Bluff{/link}. Être enterré aux Rochers rouges est le plus grand honneur que les tribus puissent accorder. Il est vieux désormais et a passé la force de l'âge, et quand des pillards {link:bristleback-quilboar}Dos-hirsute{/link} vinrent ravager les tombes, il ne put les chasser lui-même.]=],
		},
		{
			title = "Importance",
			text = [=[Raintotem garde la mémoire des morts taurens, et il appelle les vivants à la défendre. Laisser les pillards parmi les tombes ferait honte aux héros qui bâtirent la patrie des taurens.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande que les hurans soient chassés de la terre sacrée.]=],
		},
	},
	mentions = {
		{ text = "Une sépulture sacrée" },
	},
	bonds = {
		{ id = "chief-sharptusk-thornmantle", name = "Chef Sharptusk Thornmantle", note = "chef de la tribu des pillards" },
	},
})

Translate("frFR", "brave-wildrunner", {
	title = "Brave Wildrunner",
	subtitle = "Brave de Bloodhoof",
	found = "Le Village Bloodhoof",
	hint = "Parlez au brave qui veille sur le Village Bloodhoof.",
	allegiance = "Taurens · Village Bloodhoof",
	aliases = { "Wildrunner" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le brave Wildrunner garde le {link:bloodhoof-village}Village Bloodhoof{/link}. Quand la {link:longwalkers}Longwalker{/link} Malah Longwind ne revint pas de la frontière de l'est au bout de trois jours, c'est à lui qu'il revint d'apprendre ce qui s'était passé. Son devoir le retenait au village, et il envoya donc quelqu'un d'autre à sa place. La nouvelle qui revint fut la pire qu'il pût entendre. Malah avait été trouvée morte près de la lisière est de {link:mulgore}Mulgore{/link}, des flèches de centaures dans le dos et son rapport encore serré dans la main.]=],
		},
		{
			title = "Importance",
			text = [=[La vigilance de Wildrunner donna au village l'alerte du raid des Galak.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoya quelqu'un chercher la {link:longwalkers}Longwalker{/link} disparue.
• Il porta son rapport au chef {link:baine-bloodhoof}Baine Bloodhoof{/link}.]=],
		},
	},
	mentions = {
		{ text = "La {link:longwalkers}Longwalker{/link} Malah" },
		{ text = "Sinistres nouvelles" },
		{ text = "Notre ennemi ancestral" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "son chef" },
	},
})

Translate("frFR", "perith-stormhoof", {
	title = "Perith Stormhoof",
	subtitle = "Longwalker du grand chef",
	found = "À l'intérieur du Rocher des crins-pâles",
	hint = "Cherchez le tauren retenu captif dans la grotte des gnolls.",
	allegiance = "Longwalkers · Grand chef Cairne Bloodhoof",
	aliases = { "Perith" },
	sections = {
		{
			title = "Résumé",
			text = [=[Perith Stormhoof est un {link:longwalkers}Longwalker{/link}, l'un des éclaireurs de confiance du grand chef. {link:cairne-bloodhoof}Cairne{/link} l'envoya au {link:palemane-rock}Rocher des crins-pâles{/link} pour parler avec les gnolls qui s'y étaient installés. Les gnolls répondirent à ses paroles par la violence et le retinrent dans leur grotte. Le reste de sa mission, il le garde secret, comme doivent le faire tous les Longwalkers.]=],
		},
		{
			title = "Importance",
			text = [=[{link:cairne-bloodhoof}Cairne{/link} appelle Perith son éclaireur le plus sûr, et dit que sa mission est de la plus haute importance.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tenta de traiter avec les {link:palemane-gnolls}gnolls Crins-pâles{/link} au nom de {link:cairne-bloodhoof}Cairne{/link}.
• Il s'échappa du {link:palemane-rock}Rocher des crins-pâles{/link} et poursuivit seul sa tâche.]=],
		},
	},
	chapters = {
		{
			title = "L'évasion du Longwalker",
			hint = [=[Aidez le Longwalker captif à sortir du Rocher des crins-pâles.]=],
			text = [=[Une fois hors de la grotte, Perith se reposa dans la chaleur d'An'she et soigna ses blessures. Puis il repartit seul, jurant qu'il ne décevrait pas {link:cairne-bloodhoof}Cairne{/link}. Il demanda seulement que la nouvelle qu'il était sain et sauf soit portée à {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
	},
	mentions = {
		{ text = "Les {link:longwalkers}Longwalkers{/link}" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "son chef" },
	},
})

Translate("frFR", "alaana-stormwalker", {
	title = "Alaana Stormwalker",
	subtitle = "Windshaper du Camp Gev'rek",
	found = "Le Camp Gev'rek, sur le Skywatcher Plateau",
	hint = [=[Saluez la Skyborne qui accueille les voyageurs venus de Zephras Isle.]=],
	allegiance = "Windshapers · Horde",
	aliases = { "Alaana" },
	sections = {
		{
			title = "Résumé",
			text = [=[Alaana Stormwalker est une {link:skyborne}Skyborne{/link} des {link:windshapers}Windshapers{/link} descendue en {link:mulgore}Mulgore{/link} avant la plupart des siens. Elle attend au {link:camp-gev-rek}Camp Gev'rek{/link} pour accueillir chaque fendeur de ciel venu de {link:zephras-isle}Zephras Isle{/link}. Elle accueille les nouveaux venus avec joie, les prévient que le monde d'en bas est aussi dangereux que merveilleux, et leur dit que leurs nouveaux alliés sont la clé de la survie de leur peuple.]=],
		},
		{
			title = "Importance",
			text = [=[Pour les {link:windshapers}Windshapers{/link}, Alaana est la première voix d'{link:azeroth}Azeroth{/link}. Elle leur explique la {link:horde}Horde{/link} et les envoie à son chef de guerre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle accueille l'avant-garde des {link:windshapers}Windshapers{/link} en {link:mulgore}Mulgore{/link}.
• Elle envoie chaque nouveau venu auprès de {link:thrall}Thrall{/link} à {link:orgrimmar}Orgrimmar{/link}, pour parler au nom des Windshapers.]=],
		},
	},
	mentions = {
		{ text = "Le {link:earthen-ring}Cercle terrestre{/link}" },
		{ text = "Bienvenue en {link:azeroth}Azeroth{/link}" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "hôte des Windshapers" },
		{ id = "thrall", name = "Thrall", note = "le chef de guerre auprès de qui elle les envoie" },
	},
})

Translate("frFR", "muln-earthfury", {
	title = "Muln Earthfury",
	subtitle = "Ancien du Cercle terrestre",
	found = "Le Camp Gev'rek, sur le Skywatcher Plateau",
	hint = [=[Cherchez l'ancien chaman qui accueille les Skyborne en Mulgore.]=],
	allegiance = "Cercle terrestre · Taurens",
	aliases = { "Muln" },
	sections = {
		{
			title = "Résumé",
			text = [=[Muln Earthfury est un chaman {link:tauren}tauren{/link} et un chef du {link:earthen-ring}Cercle terrestre{/link}, le conseil qui garde l'équilibre des {link:elements}éléments{/link}. En ces jours, son devoir envers les esprits l'a mené au-delà du monde lui-même, jusqu'à {link:skywall}Skywall{/link}, le royaume de l'air. Là, il répondit à l'appel des {link:windshapers}Windshapers{/link}, et à son retour il les amena avec lui.]=],
		},
		{
			title = "Importance",
			text = [=[Muln est le pont entre les {link:skyborne}Skyborne{/link} et {link:azeroth}Azeroth{/link}. Par lui, les {link:windshapers}Windshapers{/link} trouvèrent le {link:earthen-ring}Cercle terrestre{/link}, et par le Cercle ils trouvèrent la {link:horde}Horde{/link}. Les elfes qui descendent en {link:mulgore}Mulgore{/link} sont ses hôtes, et ils découvrent d'abord le monde à travers son camp et ses conseils.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il répondit à la supplique de la dirigeante des {link:windshapers}Windshapers{/link}, {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, dont la patrie dépérissait.
• Il se rendit avec des chamans du {link:earthen-ring}Cercle terrestre{/link} à {link:zephras-isle}Zephras Isle{/link} pour aider les {link:skyborne}Skyborne{/link}.
• Il affronta l'un des grands seigneurs du vent et lui dit que le Cercle n'avait aucune querelle avec lui.
• Il avertit les Windshapers au sujet des seigneurs élémentaires, et des bonnes raisons de craindre {link:al-akir}Al'Akir{/link}.
• Il ouvrit une route de navires fendeurs de ciel entre Zephras Isle et {link:mulgore}Mulgore{/link}.
• Il tient le camp du {link:camp-gev-rek}Skywatcher Plateau{/link} où arrivent les nouveaux venus.]=],
		},
		{
			title = "Non consigné",
			text = [=[On écrit peu de chose de la vie de Muln avant ces jours. Les chroniques de cet âge ne disent pas quand il s'éleva à la tête du Cercle, ni comment {link:ayessa-dawnsinger}Ayessa{/link} le joignit pour la première fois à travers les plans.]=],
		},
	},
	chapters = {
		{
			title = "L'aide d'en bas",
			hint = [=[Tenez-vous aux côtés des Windshapers à leur heure la plus sombre, sur Zephras Isle.]=],
			text = [=[Les {link:windshapers}Windshapers{/link} avaient appelé à l'aide, et elle tardait à venir. Quand Muln et les chamans du {link:earthen-ring}Cercle terrestre{/link} arrivèrent enfin, la bataille contre le culte de la grande prêtresse {link:high-priestess-lorthuna}Lorthuna{/link} faisait déjà rage. Il demanda pardon à {link:ayessa-dawnsinger}Ayessa{/link} d'être venu en retard. Quand le seigneur du Vent d'est fondit sur eux, Muln parla au nom du Cercle : ils n'avaient aucune querelle avec lui, et demandaient seulement qu'on les laisse en paix. Une fois la bataille terminée, il retourna aussitôt en {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "L'avertissement",
			hint = [=[Apprenez ce que le Cercle terrestre dit aux Windshapers du seigneur des Vents.]=],
			text = [=[Muln parla longuement à {link:ayessa-dawnsinger}Ayessa{/link} des seigneurs élémentaires. Ce qu'il lui dit la laissa effrayée. Les protections qui avaient caché {link:zephras-isle}Zephras Isle{/link} avaient disparu, et rien ne se dressait plus entre l'île et {link:al-akir}Al'Akir{/link} dans son propre domaine. La grande ancienne des {link:skyborne}Skyborne{/link} voyait plus loin : pour un seigneur élémentaire, des années, voire des décennies, pourraient passer avant qu'il ne tourne les yeux vers eux.]=],
		},
		{
			title = "La route des fendeurs de ciel",
			hint = "Embarquez de Zephras Isle vers la terre du Cercle terrestre.",
			text = [=[Muln travailla dur pour rendre la traversée sûre. Des voyages d'essai furent menés entre l'île et {link:mulgore}Mulgore{/link}, où le {link:earthen-ring}Cercle terrestre{/link} a sa demeure, jusqu'à ce que les fendeurs de ciel naviguent régulièrement et que les premiers {link:skyborne}Skyborne{/link} attendent déjà de l'autre côté.]=],
		},
	},
	mentions = {
		{
			text = [=[Le {link:earthen-ring}Cercle terrestre{/link}, son camp en {link:mulgore}Mulgore{/link}]=],
		},
		{ text = "Enfant de la nature" },
		{ text = "À la découverte de la {link:horde}Horde{/link}" },
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "accueille les Windshapers à son camp" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "grand chef de son peuple" },
		{ id = "thrall", name = "Thrall", note = "chef de guerre de la Horde et chaman" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "du Cercle cénarien, qui accueille ses hôtes" },
	},
})

Translate("frFR", "kaga-wildhoof", {
	title = "Kaga Wildhoof",
	subtitle = "Voyageuse des plaines",
	found = "Un feu de camp au sud du Village Bloodhoof",
	hint = [=[Cherchez la taurène qui tient un feu de camp et une tente au sud de Bloodhoof.]=],
	allegiance = "Aventurière errante",
	aliases = { "Kaga" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kaga Wildhoof tient un feu de camp et une tente au bord de la route, au sud du {link:bloodhoof-village}Village Bloodhoof{/link}. Cette taurène des grands chemins enseigne aux jeunes l'art de {link:camping}camper{/link} : allumer un feu, disposer autour les ouvrages de chaque artisanat, et se reposer à côté jusqu'à ce que son bienfait pénètre les os.]=],
		},
		{
			title = "Importance",
			text = [=[Kaga tient que tout métier, même celui du pêcheur, a quelque chose à offrir à un camp. Par son enseignement, le vieux savoir-faire {link:tauren}tauren{/link} de la vie dans les plaines devient un art partagé par tous.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Invite les voyageurs à s'asseoir près du feu et à apprendre.
• Montre comment la tente d'un travailleur du cuir ajoute du repos à un camp.]=],
		},
	},
	mentions = {
		{
			text = [=[L'aventurière, envoyée par le chef {link:chief-hawkwind}Hawkwind{/link}]=],
		},
		{ text = "Le grand air" },
		{ text = "Camper, les bases : la cuisine" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "envoie les jeunes à Kaga" },
	},
})

Translate("frFR", "chief-sharptusk-thornmantle", {
	title = "Chef Sharptusk Thornmantle",
	subtitle = "Chef des Dos-hirsute",
	found = "Le village des hurans dans le Ravin de Roncelame",
	hint = [=[Affrontez le chef huran dans les profondeurs du Ravin de Roncelame.]=],
	allegiance = "Hurans Dos-hirsute",
	aliases = { "Sharptusk", "Sharptusk Thornmantle" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le chef Sharptusk Thornmantle mène les {link:bristleback-quilboar}hurans Dos-hirsute{/link} du {link:brambleblade-ravine}Ravin de Roncelame{/link}. Sous ses ordres, les hurans ont mené une longue guerre contre les taurens venus s'installer en {link:mulgore}Mulgore{/link}. Ses guerriers tendent des embuscades aux groupes de chasse, attaquent de nuit le camp de la {link:red-cloud-mesa}Mesa de Nuage rouge{/link} et dressent des sangliers de guerre à la cruauté.]=],
		},
		{
			title = "Importance",
			text = [=[Sharptusk est le premier ennemi que rencontrent les jeunes du {link:camp-narache}Camp Narache{/link}. Les taurens disent que leur patrie ne fut pas gagnée sans prix, et qu'une grande part de ce prix lui fut payée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mène la guerre des {link:bristleback-quilboar}Dos-hirsute{/link} contre les taurens.
• Il règne sur le village épineux au cœur du ravin.
• Son chef de guerre dressa les plans d'un long siège du {link:camp-narache}Camp Narache{/link}.]=],
		},
	},
	mentions = {
		{ text = "Brisez Sharptusk !" },
		{ text = "L'attaque du {link:camp-narache}Camp Narache{/link}" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Chef Hawkwind", note = "son ennemi" },
		{ id = "lorekeeper-raintotem", name = "Gardien du savoir Raintotem", note = "garde les tombes que sa tribu profane" },
	},
})

Translate("frFR", "supervisor-fizsprocket", {
	title = "Superviseur Fizsprocket",
	subtitle = "Contremaître de la Mine de la KapitalRisk",
	found = "Au fond de la Mine de la KapitalRisk",
	hint = [=[Affrontez le gobelin qui surveille la mine dans les falaises de l'est.]=],
	allegiance = "La KapitalRisk",
	aliases = { "Fizsprocket" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le superviseur Fizsprocket commande les gobelins de la {link:the-venture-co-mine}Mine de la KapitalRisk{/link}. Il est l'esprit derrière les plans de la compagnie pour {link:mulgore}Mulgore{/link} : chasser les taurens de leur terre afin qu'elle puisse être pillée librement. Il garde ses ordres sur une planchette, et ses papiers les plus précieux pliés dans une poche intérieure.]=],
		},
		{
			title = "Importance",
			text = [=[Les papiers de Fizsprocket révélèrent jusqu'où la {link:venture-company}KapitalRisk{/link} comptait aller, des {link:the-barrens}Tarides{/link} jusqu'aux {link:stonetalon-mountains}Serres-Rocheuses{/link} et à travers {link:mulgore}les plaines de Mulgore{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il surveille la mine dans les falaises de l'est.
• Il dressa les plans pour chasser les taurens.
• Il tenait des notes sur les déchiqueteurs et sur les travaux de la compagnie dans les {link:the-barrens}Tarides{/link}.]=],
		},
	},
	mentions = {
		{ text = "Superviseur Fizsprocket" },
		{ text = "Les notes de Fizsprocket" },
	},
	bonds = {
		{ id = "morin-cloudstalker", name = "Morin Cloudstalker", note = "veut sa mort" },
	},
})

Translate("frFR", "mazzranache", {
	title = "Mazzranache",
	subtitle = "Le trotteur aux yeux rouges",
	found = "Parcourant les plaines à l'est de Thunder Bluff",
	hint = "Affrontez le vieux trotteur aux yeux rouges brûlants.",
	allegiance = "Bêtes de Mulgore",
	sections = {
		{
			title = "Résumé",
			text = [=[Mazzranache est un trotteur des plaines de {link:mulgore}Mulgore{/link} dont parlent les récits des chasseurs de Bloodhoof. Il a des yeux rouges démoniaques, des serres tranchantes comme des rasoirs et une morsure venimeuse. Le grand-père de {link:maur-raincaller}Maur Raincaller{/link} le combattit il y a longtemps, et Maur porte à présent lui-même la marque de sa morsure. Il parcourt les plaines à l'est de {link:thunder-bluff}Thunder Bluff{/link} et ne se trouve pas facilement.]=],
		},
		{
			title = "Importance",
			text = [=[Mazzranache est l'une des vieilles terreurs des plaines. Pour extraire son poison d'une blessure, les guérisseurs de Bloodhoof ont besoin du cœur d'un loup, du fémur d'un couguar, de l'écaille d'un trotteur des plaines et du gésier d'un plongeur.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il combattit le grand-père de {link:maur-raincaller}Maur Raincaller{/link} dans des années lointaines.
• Il blessa Maur Raincaller.]=],
		},
	},
	mentions = {
		{ text = "Mazzranache" },
	},
	bonds = {
		{ id = "maur-raincaller", name = "Maur Raincaller", note = "porte sa morsure" },
	},
})

Translate("frFR", "ghost-howl", {
	title = "Ghost Howl",
	subtitle = "Le loup blanc couturé de cicatrices",
	found = "Errant dans les plaines de Mulgore",
	hint = [=[Affrontez le loup blanc qui parcourt les plaines, marqué par un ancien combat.]=],
	allegiance = "Bêtes de Mulgore",
	sections = {
		{
			title = "Résumé",
			text = [=[Ghost Howl est un grand loup blanc qui erre dans {link:mulgore}les plaines de Mulgore{/link}. Sa peau déchirée porte une terrible blessure. On dit qu'il la reçut au combat contre la {link:burning-legion}Légion ardente{/link}, et elle l'a marqué depuis. On le voit tantôt sous les falaises de {link:thunder-bluff}Thunder Bluff{/link}, tantôt dans les plaines de l'est, tantôt loin au nord.]=],
		},
		{
			title = "Importance",
			text = [=[Ghost Howl est un souvenir vivant de la guerre contre les démons, porté dans la peau d'une bête. Les chasseurs du {link:bloodhoof-village}Village Bloodhoof{/link} gardent son récit, et ils voudraient savoir s'il est tombé.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il combattit la {link:burning-legion}Légion ardente{/link} et survécut.
• Il parcourt {link:mulgore}Mulgore{/link} d'un bout à l'autre.]=],
		},
	},
	mentions = {
		{ text = "La cape marquée par les démons" },
	},
	bonds = {
		{ id = "skorn-whitecloud", name = "Skorn Whitecloud", note = "connaît son récit" },
	},
})

Translate("frFR", "herak-the-pillager", {
	title = "Herak le Pillard",
	subtitle = "Pillard des Galak",
	found = "Un camp de centaures sur la frontière est de Mulgore",
	hint = "Affrontez le pillard centaure qui a pénétré en Mulgore.",
	allegiance = "Centaures Galak",
	aliases = { "Herak" },
	sections = {
		{
			title = "Résumé",
			text = [=[Herak le Pillard mène un petit groupe de pillards {link:centaurs}centaures{/link} Galak qui s'est glissé en {link:mulgore}Mulgore{/link} depuis l'est. Ses cavaliers tuèrent la {link:longwalkers}Longwalker{/link} Malah Longwind de flèches dans le dos et dressèrent un camp à l'intérieur des frontières des taurens. Herak revendique les plaines pour les Galak et jure vengeance contre les taurens. Ses cavaliers comptaient se reposer avant de frapper le {link:bloodhoof-village}Village Bloodhoof{/link}, et envoyer chercher des renforts dans les {link:the-barrens}Tarides{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Herak est le signe que les centaures n'ont pas oublié {link:mulgore}Mulgore{/link}, et que la victoire de {link:cairne-bloodhoof}Cairne{/link} doit encore être défendue.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Ses cavaliers tuèrent la {link:longwalkers}Longwalker{/link} Malah.
• Il mena un groupe de pillards en {link:mulgore}Mulgore{/link}.]=],
		},
	},
	mentions = {
		{ text = "Chassez-les" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "veut sa tête" },
	},
})

Translate("frFR", "bristleback-quilboar", {
	title = "Hurans Dos-hirsute",
	aliases = { "hurans Dos-hirsute", "Dos-hirsute" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Dos-hirsute sont la tribu de {link:quilboar}hurans{/link} qui vit en {link:mulgore}Mulgore{/link}. Ils y étaient avant que les taurens ne s'installent dans les plaines, et ils sont en guerre contre eux depuis. De leur village épineux du {link:brambleblade-ravine}Ravin de Roncelame{/link}, ils frappent la {link:red-cloud-mesa}Mesa de Nuage rouge{/link}, et leurs pillards vont jusqu'au cimetière des {link:red-rocks}Rochers rouges{/link}, au nord.]=],
		},
		{
			title = "Façons de faire la guerre",
			text = [=[Les Dos-hirsute combattent en embuscade. Leurs guerriers guettent les groupes de chasse taurens et se glissent de nuit dans le {link:camp-narache}Camp Narache{/link}. Leurs chamans combattent à leurs côtés. Ils dressent les sangliers de guerre, les grands sangliers du ravin, à la méchanceté, et les lâchent sur les terrains de chasse des taurens. Leur chef de guerre dressa les plans d'un long siège du Camp Narache.]=],
		},
		{
			title = "En ces jours",
			text = [=[Les jeunes taurens de {link:camp-narache}Narache{/link} prouvent leur force contre les Dos-hirsute, et les ceintures des pillards tombés sont les premiers trophées du Rite de force. Des intrus Dos-hirsute ravagent depuis peu les tombes des {link:red-rocks}Rochers rouges{/link}. Leur chef, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, règne sur le ravin.]=],
		},
	},
})

Translate("frFR", "palemane-gnolls", {
	title = "Gnolls Crins-pâles",
	aliases = { "gnolls Crins-pâles", "Crins-pâles" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Crins-pâles sont une tribu de {link:gnolls}gnolls{/link} installée en {link:mulgore}Mulgore{/link}. Ils ont leur repaire dans la grotte du {link:palemane-rock}Rocher des crins-pâles{/link}, dans les collines de l'ouest, et tiennent des camps au sud du {link:bloodhoof-village}Village Bloodhoof{/link}. Ce sont des braconniers, des dépeceurs et des tanneurs, et ils massacrent la faune des plaines sans retenue.]=],
		},
		{
			title = "Les taurens et les Crins-pâles",
			text = [=[Les taurens tentèrent de partager la terre avec eux. Encore et encore, ils cherchèrent à parler aux gnolls, et chaque fois ils furent reçus avec mépris. Le chef {link:baine-bloodhoof}Baine Bloodhoof{/link} jugea enfin que les mots n'étaient plus la réponse. Malgré cela, le grand chef fit une tentative de plus en ces jours, et leur envoya son {link:longwalkers}Longwalker{/link} {link:perith-stormhoof}Perith Stormhoof{/link}. Les gnolls le saisirent et le retinrent dans leur grotte.]=],
		},
		{
			title = "Leurs repaires",
			text = [=[Les tanneurs et les dépeceurs de la tribu travaillent les peaux de leurs proies autour du {link:palemane-rock}Rocher des crins-pâles{/link}, tandis que les braconniers parcourent les collines de l'ouest. Parmi les camps au sud de Bloodhoof rôde un {link:gnolls}gnoll{/link} nommé Snagglespear.]=],
		},
	},
})

Translate("frFR", "windfury-harpies", {
	title = "Harpies Furies-des-vents",
	aliases = { "harpies Furies-des-vents", "Furies-des-vents" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Furies-des-vents sont les {link:harpies}harpies{/link} de {link:mulgore}Mulgore{/link}. Leurs volées nichent sur les bords des montagnes du sud-est, loin des routes, et surtout sur la {link:windfury-ridge}Crête des Furies-des-vents{/link}, dans le lointain nord. Les taurens les comptent parmi les ennemis naturels de leur terre.]=],
		},
		{
			title = "Nature",
			text = [=[Les volées des Furies-des-vents sont gouvernées par des matriarches, et leurs sorcières et leurs ensorceleuses commandent au vent. Elles font leur proie de tout ce qui marche sous leurs perchoirs. Leur plumage est prisé des taurens : les plumes azur et bronze des volées du nord servent aux coiffes que portent les jeunes taurens lorsqu'ils se présentent devant le grand chef.]=],
		},
		{
			title = "En ces jours",
			text = [=[{link:ruul-eagletalon}Ruul Eagletalon{/link}, de Bloodhoof, envoie de jeunes guerriers contre les volées du sud-est pour mettre leur force à l'épreuve. Les volées du nord sont plus fortes, et leurs ensorceleuses et leurs matriarches règnent sur les hauteurs de la {link:windfury-ridge}Crête des Furies-des-vents{/link}. Une {link:harpies}harpie{/link} nommée Sœur Hatelash a été vue parmi les rochers escarpés du nord-ouest, non loin du plateau où le {link:earthen-ring}Cercle terrestre{/link} a établi son camp.]=],
		},
	},
})

Translate("frFR", "longwalkers", {
	title = "Longwalkers",
	aliases = { "Longwalker" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Longwalkers sont les éclaireurs les plus sûrs des taurens. Ils ne répondent qu'au grand chef {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, et ils portent ses missions les plus secrètes. On reconnaît un Longwalker à son bandeau et à son bâton orné de plumes. Même le chef du {link:bloodhoof-village}Village Bloodhoof{/link}, le propre fils de Cairne, ne peut que leur demander leur aide.]=],
		},
		{
			title = "Leurs usages",
			text = [=[Le secret est la première loi des Longwalkers. Ils voyagent seuls, ils ne parlent pas de leurs missions, et quand l'un d'eux est tiré d'un danger, il repart seul plutôt que de dire à quiconque où il va. Quand un Longwalker ne revient pas d'une veille, les braves du village le plus proche doivent aller apprendre pourquoi.]=],
		},
		{
			title = "En ces jours",
			text = [=[Deux Longwalkers ont été en danger en {link:mulgore}Mulgore{/link}. {link:perith-stormhoof}Perith Stormhoof{/link}, que {link:cairne-bloodhoof}Cairne{/link} appelle son éclaireur le plus sûr, fut envoyé traiter avec les {link:palemane-gnolls}gnolls Crins-pâles{/link} et fut fait prisonnier. Malah Longwind fut envoyée surveiller la frontière de l'est et fut tuée par des centaures Galak, son rapport encore à la main.]=],
		},
	},
})

Translate("frFR", "rites-of-the-earthmother", {
	title = "Rites de la Terre-mère",
	aliases = { "Rites de la Terre-Mère" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Rites de la Terre-mère sont les épreuves par lesquelles un jeune {link:tauren}tauren{/link} gagne le respect des anciens de {link:thunder-bluff}Thunder Bluff{/link}. Il y en a trois : le Rite de force, le Rite de vision et le Rite de sagesse. Ensemble, ils mènent du premier camp de la {link:red-cloud-mesa}Mesa de Nuage rouge{/link} jusqu'à la hutte du grand chef.]=],
		},
		{
			title = "Les trois rites",
			text = [=[• {b}Le Rite de force.{/b} Le chef {link:chief-hawkwind}Hawkwind{/link} et le voyant {link:seer-graytongue}Graytongue{/link} envoient les jeunes contre les pillards {link:bristleback-quilboar}Dos-hirsute{/link} du {link:brambleblade-ravine}Ravin de Roncelame{/link}, pour rapporter leurs ceintures en preuve de leur bravoure.
• {b}Le Rite de vision.{/b} Au {link:bloodhoof-village}Village Bloodhoof{/link}, {link:zarlman-two-moons}Zarlman Two-Moons{/link} prépare l'Eau des voyants avec des pierres de puits et des glands d'ambre. Bue devant le feu de la tribu, elle fait naître une vision des plaines qui mène le buveur jusqu'au voyant {link:seer-wiserunner}Wiserunner{/link}.
• {b}Le Rite de sagesse.{/b} Aux {link:red-rocks}Rochers rouges{/link}, les esprits ancestraux donnent leur bénédiction à ceux qui ont bu l'Eau des voyants.]=],
		},
		{
			title = "La fin du voyage",
			text = [=[Ceux qui réussissent les rites sont honorés à {link:thunder-bluff}Thunder Bluff{/link}. Leur dernier pas est de gravir la plus haute mesa et de se présenter devant {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Même alors, l'épreuve n'est pas finie. Pour garder la place qu'ils ont gagnée, le grand chef les envoie traquer et tuer Arra'chea, un puissant kodo des plaines.]=],
		},
	},
})
